import time
START=time.monotonic()
WORKER="\nimport importlib.util,json,sys,time,traceback\nfrom pathlib import Path\nfrom fractions import Fraction\nsys.dont_write_bytecode=True\nn=int(sys.argv[1]); OUT=Path(sys.argv[2]); START=float(sys.argv[3]); OLD=Path('scripts/four-rational-kernels/step-417')/('n-'+str(n))\nstate={'n':n,'stage':'setup','panels':0}\ndef read(name): return json.loads((OLD/name).read_text())\ndef save(name,obj): (OUT/name).write_text(json.dumps(obj,sort_keys=True,separators=(',',':'))+'\\n')\ndef progress(stage,panels):\n    state.update(stage=stage,panels=panels)\n    assert time.monotonic()-START<174\n    save('working.json',{**state,'elapsed_seconds':time.monotonic()-START})\ntry:\n    spec=importlib.util.spec_from_file_location('fixed_replay_419_'+str(n),OLD/'replay.py')\n    replay=importlib.util.module_from_spec(spec); spec.loader.exec_module(replay)\n    D=replay.SCALE\n    assert D==2**256\n    signed={k:0 for k in ('floor','ceiling','multiply','divide','convert','plus','negate','clip','products','zero_operand_multiplications')}\n    signed['sign_cases']=[0]*9\n    # Fresh retained source containing only the individually reviewed primitive wrappers/controls.\n    exec(compile((OUT.parent/'signed-checks.py').read_text(),'signed-checks-419','exec'))\n    parameter=read('parameter.json')\n    assert parameter==json.loads(Path('scripts/first-rational-kernel/step-404/parameter.json').read_text())\n    assert parameter['midpoint']==[73775804382331484748893662180180200545104154546089041648426948815067512948607,2**257]\n    final=read('kernel.json')\n    progress('replay',0)\n    with (OLD/'panels.jsonl').open() as handle:\n        report=replay.run(parameter,(json.loads(line) for line in handle),final,progress)\n    assert 'n' not in report\n    assert {**report,'n':n}==read('replay.json')\n    counts=dict(replay.LEDGER)\n    assert report['counts']==counts==final['counts']\n    for name in ('producer-ledger.json','replay-ledger.json'):\n        assert read(name)=={'n':n,'counts':counts}\n    for key,expected in {'multiply':21801456,'divide':716408,'convert':5083,'negate':356616,'clip':24386}.items():\n        assert signed[key]==counts[key]==expected\n    assert signed['products']==2032 and counts['coefficient_pairs']==21264880\n    assert counts['add']==21787232==signed['plus']+21264880+1016\n    assert counts['scale']==2033 and counts['enlarge']==2034\n    assert sum(signed['sign_cases'])==signed['multiply']\n    assert signed['floor']==signed['ceiling']==signed['multiply']+signed['divide']+signed['convert']+1\n    expected=json.loads((OUT.parent/'expected-endpoints.json').read_text())[str(n)]\n    l,u,w=expected\n    assert final['n']==n and final['final_grid']==[l,u]\n    assert final['polynomial_sum']==[l+2**72,u-2**72]\n    assert u-l==2**73+w\n    assert Fraction(*final['midpoint'])==Fraction(l+u,2*D)\n    assert Fraction(*final['radius'])==Fraction(2**73+w,2*D)<Fraction(1,2**183)<Fraction(1,2**50)\n    assert final['required_radius']==[1,2**50] and final['stronger_radius']==[1,2**183]\n    assert read('parameter-identity.json')=={'n':n,'complete_record_equal':True,'midpoint_unchanged':True}\n    status=read('status.json')\n    for key,value in {'status':'PASS','n':n,'panels':1016,'pairs_per_pass':21264880,'parameter_complete_equal':True,'ledger_equal':True,'strict_radius_tests':[183,50],'radius':final['radius']}.items(): assert status[key]==value\n    save('complete-replay.json',{'status':'PASS','n':n,'replay':report,'immutable_ledger':counts,'distinct_signed_checks':signed,'parameter':parameter,'kernel':final,'sole_metadata_addition':'n','producer_executed':False,'strict_radius_powers':[183,50]})\n    state.update(stage='complete',panels=1016)\n    save('status.json',{'status':'PASS','state':state,'elapsed_seconds':time.monotonic()-START})\n    print(json.dumps({'n':n,'status':'PASS','panels':1016,'coefficient_pairs':counts['coefficient_pairs'],'strict_radius_powers':[183,50]}),flush=True)\nexcept BaseException as exc:\n    save('first-failure.json',{'type':type(exc).__name__,'message':str(exc),'state':state,'traceback':traceback.format_exc()})\n    print(json.dumps({'n':n,'status':'STOP','state':state,'error':str(exc)}),flush=True)\n    sys.exit(1)\n"
PARENT='\nimport ast,difflib,hashlib,json,math,signal,subprocess,sys,textwrap,traceback\nfrom pathlib import Path\nsys.dont_write_bytecode=True\nROOT=Path.cwd(); OLD=ROOT/\'scripts/four-rational-kernels/step-417\'; OUT=ROOT/\'scripts/four-rational-kernels/step-419\'\nLIMIT=134217728; RESERVE=73728\ninitial={}; names={}; sources={}; exits=[]; completed=[]; failure=None; current=None\nroots=[ROOT/\'scripts/first-rational-kernel\',ROOT/\'scripts/second-rational-kernel\',ROOT/\'scripts/finite-derivative-coefficients\',OLD]\ndef alarm(*args): raise TimeoutError(\'aggregate_terminal_deadline\')\nsignal.signal(signal.SIGALRM,alarm); signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\nOUT.mkdir()\nbootstrap=\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(WORKER)+\'\\nPARENT=\'+repr(PARENT)+\'\\nexec(compile(PARENT,"audit-parent-419","exec"))\\n\'\n(OUT/\'bootstrap.py\').write_text(bootstrap); (OUT/\'worker.py\').write_text(WORKER)\ndef disk(): return sum(p.stat().st_size for p in OUT.rglob(\'*\') if p.is_file())\ndef sha(raw): return hashlib.sha256(raw).hexdigest()\ndef inventory(paths):\n    answer={}\n    for p in sorted(set(paths)):\n        raw=p.read_bytes(); answer[str(p.relative_to(ROOT))]={\'bytes\':len(raw),\'sha256\':sha(raw)}\n    return answer\ndef tree_names(): return {str(root.relative_to(ROOT)):sorted(str(p.relative_to(ROOT)) for p in root.rglob(\'*\') if p.is_file()) for root in roots}\ndef save(name,obj):\n    raw=(json.dumps(obj,sort_keys=True,separators=(\',\',\':\'))+\'\\n\').encode()\n    assert disk()+len(raw)+RESERVE<=LIMIT\n    (OUT/name).write_bytes(raw)\ndef read(name): return json.loads((OLD/name).read_text())\ndef workcheck():\n    assert time.monotonic()-START<174 and disk()+RESERVE<=LIMIT\ntry:\n    original=read(\'initial-inventory.json\'); assert len(original)==95\n    names=tree_names()\n    selected=[\'lemmas/L105-four-fixed-rational-kernel-certificates.md\',\'drafts/literature/2026-10-23-four-kernel-certificate-audit.md\',\'drafts/source-notes/2026-10-23-four-kernel-audit-coverage.md\',\'drafts/2026-10-23-four-kernel-document-transition.json\',\'drafts/2026-10-23-four-kernel-critical-audit.md\']\n    initial=inventory([ROOT/p for p in original]+[p for p in OLD.rglob(\'*\') if p.is_file()]+[ROOT/p for p in selected])\n    save(\'initial-inventory.json\',initial)\n    transition=json.loads((ROOT/selected[3]).read_text())\n    changed=\'drafts/2026-10-23-four-kernel-attempt.md\'\n    assert set(transition[\'files\'])=={changed}\n    assert transition[\'files\'][changed][\'before\']==original[changed]\n    assert transition[\'files\'][changed][\'after\']==initial[changed]\n    for rel,value in original.items():\n        assert initial[rel]==(transition[\'files\'][rel][\'after\'] if rel in transition[\'files\'] else value),(\'original_input\',rel)\n    for root in roots[:-1]:\n        prefix=str(root.relative_to(ROOT))+\'/\'\n        assert names[str(root.relative_to(ROOT))]==sorted(p for p in original if p.startswith(prefix))\n    assert read(\'preservation.json\')=={\'count\':95,\'files\':original,\'mismatches\':[],\'original_tree_file_sets_equal\':True,\'fresh_sources_equal\':True,\'all_match\':True}\n    # Parse old bootstrap solely as data; never execute worker or parent entrypoints.\n    tree=ast.parse((OLD/\'bootstrap.py\').read_text())\n    literals={node.targets[0].id:ast.literal_eval(node.value) for node in tree.body if isinstance(node,ast.Assign) and isinstance(node.targets[0],ast.Name) and node.targets[0].id in (\'WORKER\',\'PARENT\')}\n    assert set(literals)=={\'WORKER\',\'PARENT\'}\n    assert literals[\'WORKER\']==(OLD/\'worker.py\').read_text()\n    assert (OLD/\'bootstrap.py\').read_text()==\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(literals[\'WORKER\'])+\'\\nPARENT=\'+repr(literals[\'PARENT\'])+\'\\nexec(compile(PARENT,"batch-parent","exec"))\\n\'\n    parent_tree=ast.parse(literals[\'PARENT\'])\n    nodes=[x for x in ast.walk(parent_tree) if isinstance(x,ast.Assign) and any(isinstance(t,ast.Name) and t.id==\'replacements\' for t in x.targets)]\n    assert len(nodes)==1\n    # Only this inspected data expression is evaluated: constants, f-strings, n and str(n).\n    allowed=(ast.Dict,ast.List,ast.Tuple,ast.Constant,ast.JoinedStr,ast.FormattedValue,ast.Name,ast.Load,ast.BinOp,ast.Add,ast.Call)\n    assert all(isinstance(x,allowed) for x in ast.walk(nodes[0].value))\n    assert all(x.id in (\'n\',\'str\') for x in ast.walk(nodes[0].value) if isinstance(x,ast.Name))\n    assert all(isinstance(x.func,ast.Name) and x.func.id==\'str\' for x in ast.walk(nodes[0].value) if isinstance(x,ast.Call))\n    source_hashes=read(\'source-hashes.json\')\n    assert len(source_hashes)==10 and inventory([ROOT/p for p in source_hashes])==source_hashes\n    assert set(source_hashes)=={str((OLD/f).relative_to(ROOT)) for f in (\'bootstrap.py\',\'worker.py\')}|{str((OLD/(\'n-\'+str(n))/f).relative_to(ROOT)) for n in (3,4,5,6) for f in (\'producer.py\',\'replay.py\')}\n    reviews=[]\n    for n in (3,4,5,6):\n        dest=OLD/(\'n-\'+str(n)); review=json.loads((dest/\'source-review.json\').read_text())\n        transforms=eval(compile(ast.Expression(nodes[0].value),\'data-expression\',\'eval\'),{\'__builtins__\':{},\'str\':str},{\'n\':n})\n        assert review=={\'n\':n,\'unique_exact_changes\':{k:[{\'old\':a,\'new\':b} for a,b in v] for k,v in transforms.items()},\'both_scalar_and_beta_arguments_bound\':True,\'midpoint_not_scaled\':True,\'all_independent_arithmetic_and_full_loops_unchanged\':True}\n        differences=[]\n        for name,pairs in transforms.items():\n            before=(ROOT/\'scripts/second-rational-kernel/step-412\'/name).read_text(); after=before\n            for a,b in pairs:\n                assert after.count(a)==1; after=after.replace(a,b,1)\n            assert after==(dest/name).read_text(); ast.parse(after)\n            differences.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile=\'step-412/\'+name,tofile=\'n-\'+str(n)+\'/\'+name))\n        assert \'\'.join(differences)==(dest/\'source-diff.txt\').read_text()\n        reviews.append(review)\n    manifest=read(\'manifest.json\')\n    expected={\'step\':\'BSD-2026-10-23-417-four-kernel-batch\',\'indices\':[3,4,5,6],\'required_seconds\':180,\'work_deadline_seconds\':174,\'required_new_bytes\':LIMIT,\'report_and_diagnostic_reserve\':RESERVE,\'midpoint\':\'unchanged complete L103 record\',\'panels_per_kernel\':1016,\'factor_slots\':[129,65,65],\'product_slots\':[193,257],\'pairs_per_pass\':21264880,\'scalar_terms\':128,\'scalar_squares\':16,\'grid_fractional_bits\':256,\'analytic_enlargement_grid\':2**72,\'strict_radius_powers\':[183,50],\'source_generation_in_cap\':True,\'isolated_modules_per_child\':True,\'old_entrypoints_executed\':False,\'no_retry_or_resumption\':True}\n    assert {k:v for k,v in manifest.items() if k!=\'python\'}==expected\n    assert manifest[\'python\'].startswith(\'3.15.0\')\n    term=read(\'terminal-report.json\'); fin=read(\'finalization.json\'); hist_exits=read(\'observed-child-exits.json\'); hist_completed=read(\'completed-kernels.json\')\n    assert term[\'child_exits\']==hist_exits and term[\'completed_indices\']==[3,4,5,6]\n    assert term[\'status\']==\'PASS\' and term[\'failure\'] is None and term[\'preservation\'] and term[\'preserved_inputs\']==95 and term[\'terminal_timer_retained\']\n    assert term[\'required_seconds\']==180 and term[\'required_new_bytes\']==LIMIT and term[\'path\']==\'scripts/four-rational-kernels/step-417/terminal-report.json\'\n    prev=0\n    for n,ex,st in zip((3,4,5,6),hist_exits,hist_completed,strict=True):\n        assert ex[\'n\']==n and ex[\'returncode\']==0 and prev<ex[\'start_seconds\']<ex[\'observed_exit_seconds\']<term[\'elapsed_before_terminal_seconds\']\n        prev=ex[\'observed_exit_seconds\']\n        dest=OLD/(\'n-\'+str(n)); assert st==json.loads((dest/\'status.json\').read_text())\n        assert st[\'elapsed_seconds\']<ex[\'observed_exit_seconds\']\n        work=json.loads((dest/\'working.json\').read_text()); assert work[\'n\']==n and work[\'stage\']==\'replay\' and work[\'panels\']==961 and work[\'elapsed_seconds\']<st[\'elapsed_seconds\']\n        output=json.loads((dest/\'child-stdout.txt\').read_text()); assert output=={\'n\':n,\'status\':\'PASS\',\'radius\':st[\'radius\']}\n        assert (dest/\'child-stderr.txt\').read_bytes()==b\'\'\n    fixed=list(OLD.rglob(\'*\')); before=sum(p.stat().st_size for p in fixed if p.is_file() and p.name not in (\'terminal-report.json\',\'finalization.json\'))\n    assert before+RESERVE==term[\'inclusive_new_bytes\']==fin[\'inclusive_new_bytes\']==6025081\n    assert math.ceil(term[\'elapsed_before_terminal_seconds\'])+2==term[\'inclusive_seconds\']==fin[\'inclusive_seconds\']==105\n    assert before+(OLD/\'terminal-report.json\').stat().st_size==fin[\'new_bytes_after_terminal\']\n    assert term[\'elapsed_before_terminal_seconds\']<fin[\'elapsed_after_terminal_seconds\']<105\n    assert fin[\'all_children_observed_before_terminal\'] and fin[\'parent_exit_time_not_claimed\'] and fin[\'terminal_timer_retained\']\n    assert sum(p.stat().st_size for p in fixed if p.is_file())+8192<=6025081\n    save(\'historical-review.json\',{\'manifest\':manifest,\'source_reviews\':reviews,\'source_hashes\':source_hashes,\'exact_bootstrap_worker_and_adaptations\':True,\'transition\':transition,\'terminal\':term,\'finalization\':fin,\'before_terminal_bytes\':before,\'qualification\':\'Historical n=1 finalization, n=2 bootstrap/process exit and step-417 exact parent exit remain unverified as originally qualified.\'})\n    # Extract only the reviewed wrappers/controls as fresh source; no old audit entrypoint runs.\n    old_checks=(ROOT/\'scripts/second-rational-kernel/step-415/audit-body.py\').read_text()\n    a=\'    old_floor,old_ceil=replay.floor_checked,replay.ceil_checked\\n\'; b=\'    parameter=read(\\\'parameter.json\\\')\\n\'\n    assert old_checks.count(a)==old_checks.count(b)==1\n    checks=textwrap.dedent(old_checks[old_checks.index(a):old_checks.index(b)])\n    ast.parse(checks); (OUT/\'signed-checks.py\').write_text(checks)\n    endpoints={}\n    for line in (ROOT/selected[0]).read_text().splitlines():\n        if line.startswith(\'| \') and line.split(\'|\')[1].strip() in (\'3\',\'4\',\'5\',\'6\'):\n            values=[int(v.strip()) for v in line.split(\'|\')[1:-1]]; endpoints[str(values[0])]=values[1:]\n    assert set(endpoints)=={\'3\',\'4\',\'5\',\'6\'} and [endpoints[str(n)][2] for n in (3,4,5,6)]==[922672,466423,252182,142692]\n    save(\'expected-endpoints.json\',endpoints)\n    sources=inventory([OUT/\'bootstrap.py\',OUT/\'worker.py\',OUT/\'signed-checks.py\',OUT/\'expected-endpoints.json\'])\n    save(\'fresh-source-hashes.json\',sources)\n    save(\'audit-manifest.json\',{\'python\':sys.version,\'indices\':[3,4,5,6],\'time_cap_seconds\':180,\'byte_cap\':LIMIT,\'start_before_setup\':True,\'old_entrypoints_executed\':False,\'source_generation_in_cap\':True,\'signed_checks\':\'exact reviewed wrapper/control block only; all remaining additions/scales/enlargements reconciled with full ledgers and source inspection\'})\n    for n in (3,4,5,6):\n        current=n; workcheck(); dest=OUT/(\'n-\'+str(n)); dest.mkdir(); t=time.monotonic()-START\n        try:\n            result=subprocess.run([sys.executable,\'-B\',str(OUT/\'worker.py\'),str(n),str(dest),repr(START)],capture_output=True,timeout=max(.001,174-(time.monotonic()-START)))\n            stdout,stderr,code=result.stdout,result.stderr,result.returncode\n        except subprocess.TimeoutExpired as exc:\n            stdout,stderr,code=exc.stdout or b\'\',exc.stderr or b\'\',None\n            failure={\'type\':\'ChildTimeout\',\'n\':n,\'message\':\'child killed and waited; no retry\'}\n        assert len(stdout)+len(stderr)<=8192\n        (dest/\'child-stdout.txt\').write_bytes(stdout); (dest/\'child-stderr.txt\').write_bytes(stderr)\n        exits.append({\'n\':n,\'returncode\':code,\'start_seconds\':t,\'observed_exit_seconds\':time.monotonic()-START}); save(\'observed-child-exits.json\',exits)\n        if failure is not None: break\n        if code!=0:\n            failure={\'type\':\'ChildFailure\',\'n\':n,\'returncode\':code,\'evidence\':str((dest/\'first-failure.json\').relative_to(ROOT))}; break\n        completed.append(n); save(\'completed-indices.json\',completed)\n        print(json.dumps({\'n\':n,\'status\':\'PASS\',\'observed_exit_seconds\':exits[-1][\'observed_exit_seconds\']}),flush=True)\n        workcheck()\nexcept BaseException as exc:\n    if failure is None: failure={\'type\':type(exc).__name__,\'message\':str(exc),\'n\':current,\'traceback\':traceback.format_exc()}\nfinally:\n    signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\n    after=inventory([ROOT/p for p in initial]); mismatch=[p for p in initial if initial[p]!=after.get(p)]\n    preserved=not mismatch and tree_names()==names and inventory([ROOT/p for p in sources])==sources\n    save(\'preservation.json\',{\'count\':len(initial),\'files\':after,\'mismatches\':mismatch,\'all_match\':preserved,\'tree_sets_equal\':tree_names()==names,\'fresh_sources_equal\':inventory([ROOT/p for p in sources])==sources})\n    if not preserved and failure is None: failure={\'type\':\'PreservationFailure\',\'message\':str(mismatch)}\n    if failure is not None: save(\'first-failure.json\',failure)\n    elapsed=time.monotonic()-START; sec=math.ceil(elapsed)+2; size=disk()+RESERVE\n    okay=failure is None and completed==[3,4,5,6] and sec<=180 and size<=LIMIT\n    terminal={\'status\':\'PASS\' if okay else \'STOP\',\'completed_indices\':completed,\'failure\':failure,\'child_exits\':exits,\'preserved_inputs\':len(initial),\'preservation\':preserved,\'elapsed_before_terminal_seconds\':elapsed,\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\'required_seconds\':180,\'required_new_bytes\':LIMIT,\'terminal_timer_retained\':True,\'path\':str((OUT/\'terminal-report.json\').relative_to(ROOT))}\n    save(\'terminal-report.json\',terminal)\n    # Rehash again after terminal reporting, so the preservation boundary covers reporting.\n    assert inventory([ROOT/p for p in initial])==initial and tree_names()==names and inventory([ROOT/p for p in sources])==sources\n    save(\'finalization.json\',{\'elapsed_after_terminal_seconds\':time.monotonic()-START,\'new_bytes_after_terminal\':disk(),\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\'all_children_observed_before_terminal\':True,\'preservation_rechecked_after_terminal\':True,\'parent_exit_time_not_claimed\':True,\'terminal_timer_retained\':True})\n    assert time.monotonic()-START<=sec<=180 and disk()+8192<=size<=LIMIT\n    print(json.dumps(terminal),flush=True)\n    assert time.monotonic()-START<=sec\n    sys.exit(0 if okay else 1)\n'
exec(compile(PARENT,"audit-parent-419","exec"))
